import re
import os
from dateutil import parser
from dateutil.parser import ParserError
from taf.analyzer.ims2 import Ims2LogReader
from taf.ul.oam_kpi_calculations.parsers.ims.patterns import DistNamePatterns


def get_timestamp_in_datetime_format(timestamp):
    if not isinstance(timestamp, datetime.datetime):
        try:
            timestamp_with_z_postfix = "{}Z".format(timestamp)
            parsed_timestamp = parser.parse(timestamp_with_z_postfix)
        except ParserError:
            parsed_timestamp = parser.parse(timestamp)
    else:
        parsed_timestamp = timestamp

    return parsed_timestamp


def normalize_dist_name(dist_name, escape_pattern=False):
    r"""
    Normalize dist_name by replacing /RUNTIME_VIEW-\d+/MRBTS_\w+-\d+ segment with /...
    This allows matching cells that have different RUNTIME_VIEW and MRBTS_R values (e.g., during role switchover).

    :param str dist_name: Original dist_name
    :return str: Normalized dist_name with /... instead of /RUNTIME_VIEW-\d+/MRBTS_R-\d+
    """
    # Replace /RUNTIME_VIEW-\d+/MRBTS_\w+-\d+ segment with /...
    pattern = r'/RUNTIME_VIEW-\d+/MRBTS_\w+-\d+'
    if escape_pattern:
        pattern = re.escape(pattern)
    normalized = re.sub(pattern, '/...', dist_name)
    return normalized


def get_cell_id_from_dist_name(dist_name):
    """
    Get cell ID from passed dist name.

    :param str dist_name: dist name eg: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427
    :return int: cell id
    """
    cell_id = None
    re_cell_id = re.compile(r'-(?P<CELL_ID>\d+)$')
    match_cell_id = re_cell_id.search(dist_name)
    if match_cell_id:
        cell_id = int(match_cell_id.group('CELL_ID'))

    return cell_id


_re_cell_info = re.compile(DistNamePatterns.CELL_INFO)
_cell_info_normalized_pattern = normalize_dist_name(DistNamePatterns.CELL_INFO, escape_pattern=True)
_re_cell_info_normalized = re.compile(_cell_info_normalized_pattern)


def is_cell_dist_name(dist_name):
    r"""
    Check if dist_name is a cell dist name.
    Supports both normal and normalized dist names (with /... instead of /RUNTIME_VIEW-\d+/MRBTS_\w+-\d+).

    :param str dist_name: dist name eg: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427
                          or normalized: /MRBTS-1/RAT-1/.../LNBTS_R-10342/LNCEL_R-48427
    :return bool: True if dist_name is a cell dist name, False otherwise
    """
    # First check if it's already a normalized dist_name (contains /...)
    if _re_cell_info_normalized.search(dist_name):
        return True
    # Check normal pattern
    if _re_cell_info.search(dist_name):
        return True

    return False


def compare_cells_number_in_results(results):
    """
    Check if cells detected in 'start_points' is the same as in 'end_points'
    :param dict results: standard results from oam_kpi interface eg:
        results = {
            "kpi1a": [
                {
                    "delta": "0:01:26.020000",
                    "end_points": {
                        "GSM": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/GNBTS_R-1/GNBCF_R-1/GNCEL_CONF_M-1/GNCEL_R-1": [
                                "2022-05-19 12:06:53.027000+00:00"
                            ]
                        },
                        "LTE": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427": [
                                "2022-05-19 12:06:51.528000+00:00"
                            ]
                        },
                        "WCDMA": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/WNBTS_R-1/WNCEL_R-33420": [
                                "2022-05-19 12:07:05.528000+00:00"
                            ]
                        }
                    },
                    "start_point_timestamp": "2022-05-19 12:05:39.508000+00:00",
                    "start_points": {
                        "GSM": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/GNBTS_R-1/GNBCF_R-1/GNCEL_CONF_M-1/GNCEL_R-1": [
                                "2022-05-19 12:05:39.508000+00:00",
                                "2022-05-19 12:06:46.027000+00:00"
                            ]
                        },
                        "LTE": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427": [
                                "2022-05-19 12:05:39.508000+00:00"
                            ]
                        },
                        "WCDMA": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/WNBTS_R-1/WNCEL_R-33420": [
                                "2022-05-19 12:05:39.508000+00:00"
                            ]
                        }
                    }
                    .....
                }
                ....
            ],

            "kpi1b": [
             ....
            ]
        }
    :return bool: True/False
    """
    for kpi_name in results:
        for single_results in results[kpi_name]:
            cell_ids = _get_cell_ids_from_results(single_results)
            if cell_ids['start_points'] != cell_ids['end_points']:
                logging.debug("Cell IDs from start_points are different "
                              "than Cell IDs from end_points {}".format(cell_ids))
                return False
    return True


def compare_configured_cells_with_results_cells(results, configured_cells):
    """
    Compare cell configured in BTS with detected in 'end_points'
    Keyword useful to ensure all cell were detected during site reset

    :param dict results: standard results from oam_kpi interface eg:
        results = {
            "kpi1a": [
                {
                    "delta": "0:01:26.020000",
                    "end_points": {
                        "GSM": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/GNBTS_R-1/GNBCF_R-1/GNCEL_CONF_M-1/GNCEL_R-1": [
                                "2022-05-19 12:06:53.027000+00:00"
                            ]
                        },
                        "LTE": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427": [
                                "2022-05-19 12:06:51.528000+00:00"
                            ]
                        },
                        "WCDMA": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/WNBTS_R-1/WNCEL_R-33420": [
                                "2022-05-19 12:07:05.528000+00:00"
                            ]
                        }
                    },
                    "start_point_timestamp": "2022-05-19 12:05:39.508000+00:00",
                    "start_points": {
                        "GSM": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/GNBTS_R-1/GNBCF_R-1/GNCEL_CONF_M-1/GNCEL_R-1": [
                                "2022-05-19 12:05:39.508000+00:00",
                                "2022-05-19 12:06:46.027000+00:00"
                            ]
                        },
                        "LTE": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-10342/LNCEL_R-48427": [
                                "2022-05-19 12:05:39.508000+00:00"
                            ]
                        },
                        "WCDMA": {
                            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/WNBTS_R-1/WNCEL_R-33420": [
                                "2022-05-19 12:05:39.508000+00:00"
                            ]
                        }
                    }
                    .....
                }
                ....
            ],

            "kpi1b": [
             ....
            ]
        }
    :param list configured_cells: List of configured global cell IDs.
    :return bool: True/False
    """
    for kpi_name in results:
        for single_results in results[kpi_name]:
            cell_ids = _get_cell_ids_from_results(single_results)
            if cell_ids['end_points'] != set(configured_cells):
                logging.warning("Cell IDs from IMS file: {} are different "
                                "than configured cell ids: {}".format(cell_ids['end_points'], configured_cells))
                return False
    return True


def get_last_disconnected_ims_log(log_dir, log_name_regex=None):
    def extract_datetime_from_filename(filename):
        match = re.search(r'disconnect_at_([\w\d]+)GMT', filename)
        if match:
            date_str = match.group(1)
            return datetime.datetime.strptime(date_str, "%a%d%b%Y%H%M%S")

    # admin_api_REST_GNB0_DU0_disconnect_at_Fri24Jun2022134933GMT
    if log_name_regex is None:
        log_name_regex = r'admin_api.*disconnect_at.*\.ims2$'

    compiled_regex = re.compile(log_name_regex)
    files = filter(compiled_regex.search, os.listdir(log_dir))
    files = [os.path.join(log_dir, f) for f in files]

    files.sort(key=lambda x: extract_datetime_from_filename(os.path.basename(x)))
    logging.debug("ALL disconnected files under dir [{}] {} ".format(log_dir, files))
    if files:
        return files[-1]


def merge_and_sort_ims_files(ims_file_paths):  # noqa: C901
    """
    Merge and sort IMS files
    :param ims_file_paths: list of ims files path.
    """

    def fullfill_records_before_mrbts_id_is_set(records_before_mrbts_id_is_set, mrbts_id, ims_path):
        for frame_number, log_entry in enumerate(records_before_mrbts_id_is_set):
            entries.append(
                {'entry': log_entry, 'frame': frame_number, 'file_path': ims_path, 'mrbts_id': mrbts_id})

    entries = []
    mrbts_ids = set()
    for ims_path in ims_file_paths:
        mrbts_id = None
        records_before_mrbts_id_is_set = []
        for frame_number, log_entry in enumerate(Ims2LogReader.from_file(file_path=ims_path)):
            if mrbts_id is None:
                mrbts_id = get_mrbts_from_log_entry(log_entry)
                if mrbts_id is None:
                    records_before_mrbts_id_is_set.append(log_entry)
                    continue
                logging.debug("Merging IMS from: {}".format(mrbts_id))
                mrbts_ids.add(mrbts_id)
                fullfill_records_before_mrbts_id_is_set(records_before_mrbts_id_is_set, mrbts_id, ims_path)
            entries.append({'entry': log_entry, 'frame': frame_number, 'file_path': ims_path, 'mrbts_id': mrbts_id})
    entries.sort(key=lambda record: record['entry'].timestamp)
    return entries, mrbts_ids


def get_mrbts_from_log_entry(log_entry):
    re_mrbts = re.compile(DistNamePatterns.MRBTS_A)
    for dist_name in log_entry.updates.keys():
        match = re_mrbts.search(dist_name)
        if match:
            return "MRBTS-{}".format(match.group('BTS_ID'))


def custom_json_serializable(obj):
    if hasattr(obj, 'to_dict') and callable(obj.to_dict):
        return obj.to_dict()
    else:
        return obj.__str__()


def _get_cell_ids_from_results(results):
    """
    Get set of cell ids from single KPI result

    :param results: single KPI result
    :return:
    """
    cell_ids = {}
    keys_to_check = {'start_points', 'end_points'}
    for key in keys_to_check:
        cell_ids[key] = set()
        for rat in results[key]:
            for dist_name in results[key][rat]:
                cell_id = get_cell_id_from_dist_name(dist_name)
                if cell_id:
                    cell_ids[key].add(cell_id)
    return cell_ids


def try_to_int(value):
    try:
        return int(value)
    except (ValueError, TypeError):
        return value
